import{_ as t,o as i,c as r,a3 as a}from"./chunks/framework.BwzYn71E.js";const d=JSON.parse('{"title":"Logistics Principles and Some Terms","description":"","frontmatter":{"translationSource":{"title":"物流原理与一些名词","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=Ul3PjfHfEH7t9ofd3SfA1L","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/logistics-principles-and-frontier-research"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/logistics-principles-and-frontier-research"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/logistics-principles-and-frontier-research"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/logistics-principles-and-frontier-research"}]]},"headers":[],"relativePath":"logistics-principles-and-frontier-research.md","filePath":"logistics/src/page-Ul3PjfHfEH7t9ofd3SfA1L.md"}'),o={name:"logistics-principles-and-frontier-research.md"};function s(n,e,l,c,u,p){return i(),r("div",null,[...e[0]||(e[0]=[a('<div class="logistics-content"><h1 id="logistics-principles-and-some-terms" tabindex="-1">Logistics Principles and Some Terms <a class="header-anchor" href="#logistics-principles-and-some-terms" aria-label="Permalink to &quot;Logistics Principles and Some Terms&quot;">​</a></h1><blockquote><p>Source page ID: <code>Ul3PjfHfEH7t9ofd3SfA1L</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=Ul3PjfHfEH7t9ofd3SfA1L" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p><span class="mark-red"><strong>Severely unmaintained. Discuss whether this page&#39;s subpage organization is appropriate.</strong></span></p><p><span id="source-block-wO7xPIiHDJwfeAtqFW4VJE"></span></p><h2 id="uniformity-and-range" tabindex="-1">Uniformity and Range <a class="header-anchor" href="#uniformity-and-range" aria-label="Permalink to &quot;Uniformity and Range&quot;">​</a></h2><p><span id="source-block-Ik2ViXezbe9d6VFUOZIUc6"></span></p><h2 id="definitions-of-various-special-structures" tabindex="-1">Definitions of Various Special Structures <a class="header-anchor" href="#definitions-of-various-special-structures" aria-label="Permalink to &quot;Definitions of Various Special Structures&quot;">​</a></h2><p><span id="source-block-f5f4WE5OyQHLDbhWbKgmAv"></span></p><h3 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h3><p>Narrow-sense filter: converts a nonuniform input sequence into a more uniform sequence, e.g. 10110 10011 → 10110 10110. Sometimes also called a flow stabilizer.</p><p>With full-belt input, equivalent to a comparatively uniform flow limiter.</p><p>Broad-sense filter: low-pass diverts sequence flow exceeding the specified flow-rate range elsewhere, usually by inserting it into a sequence below the specified flow-rate range or out of the structure. High-pass is the opposite.</p><p><span id="source-block-9j2XLqzFcpwJ8W5QQIYeRK"></span></p><h3 id="flow-regularizers" tabindex="-1">Flow Regularizers <a class="header-anchor" href="#flow-regularizers" aria-label="Permalink to &quot;Flow Regularizers&quot;">​</a></h3><p>Narrow-sense flow regularizer: converts the input sequence into consecutive 1/0 runs, e.g. 10110 10011 → 11100 11100.</p><p>With full-belt input, transmits a blocking signal with consecutive 1/0 runs upstream.</p><p>Broad-sense flow regularizer: converts the input flow into a specifically structured flow; typically into continuous flow alternating with 0 flow, and also into particular sequences such as perfectly uniform ones.</p><p><span id="source-block-dey4t7kblTAWoIHHqzUYE7"></span></p><h3 id="overflow-routers" tabindex="-1">Overflow Routers <a class="header-anchor" href="#overflow-routers" aria-label="Permalink to &quot;Overflow Routers&quot;">​</a></h3><p>Narrow-sense overflow router: the input has a strict priority relation between two output ports, that is, B receives no flow until A is too full to output.</p><p>Broad-sense overflow router: the input has a non-strict priority relation between two output ports, that is, under no-load conditions the flow output toward the high-priority direction A is greater than A&#39;s maximum passable flow rate when fully loaded.</p><p><span id="source-block-n9B7tFb0RiVmFdwgWv9DxN"></span></p><h3 id="flow-limiters" tabindex="-1">Flow Limiters <a class="header-anchor" href="#flow-limiters" aria-label="Permalink to &quot;Flow Limiters&quot;">​</a></h3><p>A single-inlet, single-outlet logistics structure that limits the upper bound of the average flow rate passing through it and does not guarantee a specific output sequence. Sometimes also called a rate limiter.</p><p><span id="source-block-gk0ftJwaqdj335twrpq0qB"></span></p><h3 id="priority-convergers" tabindex="-1">Priority Convergers <a class="header-anchor" href="#priority-convergers" aria-label="Permalink to &quot;Priority Convergers&quot;">​</a></h3><p>A splitter→converger; conveyor→converger structure built on the principle of merge priority. Because the total flow rate is less than or equal to 1, when the input flow rate in the high-priority direction is 1, the low-priority direction&#39;s flow rate becomes 0, so the low-priority direction is &quot;blocked&quot;.</p><p><span id="source-block-Tr4QvYq1Ruz7WvejwO5RcS"></span></p><h3 id="screeners-filters-sorters-separators" tabindex="-1">Screeners \\ Filters \\ Sorters \\ Separators <a class="header-anchor" href="#screeners-filters-sorters-separators" aria-label="Permalink to &quot;Screeners \\ Filters \\ Sorters \\ Separators&quot;">​</a></h3><p>References within this section always use the name sorter. In essence this is a splitter→a container that can accept only a certain fluid \\ item; the container is usually a filtering control port. When there are special requirements (压元件 “item compression”, 压地 “ground compression” — tentative), devices such as pipes \\ conduits that can store only one kind of fluid, or the activator port of the Solid-Gas \\ Fluid-Gas Transmuting Unit that accepts only activators, are used instead of a container.</p><p><span id="source-block-43mxU8WxSkD6eR8LkKUVn8"></span></p><h3 id="inverters-recirculators" tabindex="-1">Inverters \\ Recirculators <a class="header-anchor" href="#inverters-recirculators" aria-label="Permalink to &quot;Inverters \\ Recirculators&quot;">​</a></h3><p><span id="source-block-TwAdfmWti8bBHTAGCmTcqt"></span></p><h3 id="basic-control-structure" tabindex="-1">Basic Control Structure <a class="header-anchor" href="#basic-control-structure" aria-label="Permalink to &quot;Basic Control Structure&quot;">​</a></h3><p>A basic control structure is a two-input, two-output structure in which the two kinds of input each correspond to one output, with one control side and one controlled side; when the flow rate on the control side is 1, the controlled side is blocked.</p><p><span id="source-block-msCpcnAU4hdiRv7T0efvi5"></span></p><h4 id="solid-solid-liquid-liquid-basic-control-structure" tabindex="-1">Solid-Solid \\ Liquid-Liquid Basic Control Structure <a class="header-anchor" href="#solid-solid-liquid-liquid-basic-control-structure" aria-label="Permalink to &quot;Solid-Solid \\ Liquid-Liquid Basic Control Structure&quot;">​</a></h4><p>The usual implementation is priority converger→sorter, which ensures that both inputs and outputs are of exactly two pure kinds, while the characteristics of the priority converger make one input control the other input. The overall effect is similar to a priority converger, except that the outputs are of multiple kinds.</p><p><span id="source-block-WAa6YT2JcwqSHP14sGqTCT"></span></p><h4 id="solid-liquid-basic-control-structure" tabindex="-1">Solid-Liquid Basic Control Structure <a class="header-anchor" href="#solid-liquid-basic-control-structure" aria-label="Permalink to &quot;Solid-Liquid Basic Control Structure&quot;">​</a></h4><p>Usual implementation 1: an unpowered reaction tank can accept both solids and liquids, allowing their amounts to rise and fall together (in the same slot). Combined with an inverter, this implements the basic control structure. Likewise, facilities with a recipe that uses both liquid and solid inputs can directly make the two amounts rise and fall together.</p><p>Usual implementation 2: similar to the unpowered case</p><p><span id="source-block-BKd0bfBqMQYjGOon5TjRNh"></span></p><h3 id="uniform-binary-splitters" tabindex="-1">Uniform Binary Splitters <a class="header-anchor" href="#uniform-binary-splitters" aria-label="Permalink to &quot;Uniform Binary Splitters&quot;">​</a></h3><p><span id="source-block-S59ZGmLv5iYu3bJX0M4vLU"></span></p><h4 id="bresenham-algorithm" tabindex="-1">Bresenham Algorithm <a class="header-anchor" href="#bresenham-algorithm" aria-label="Permalink to &quot;Bresenham Algorithm&quot;">​</a></h4><p><span id="source-block-rJLuoyW0sbNOPnKggEQMI8"></span></p><h2 id="uniformity-of-simple-rational-splitters" tabindex="-1">Uniformity of Simple Rational Splitters <a class="header-anchor" href="#uniformity-of-simple-rational-splitters" aria-label="Permalink to &quot;Uniformity of Simple Rational Splitters&quot;">​</a></h2><p><span id="source-block-saFuJ384PvuWkO0x5E0uld"></span></p><h2 id="uniform-rational-rate-limiters" tabindex="-1">Uniform Rational-Rate Limiters <a class="header-anchor" href="#uniform-rational-rate-limiters" aria-label="Permalink to &quot;Uniform Rational-Rate Limiters&quot;">​</a></h2><p><span id="source-block-Uj5kS4ulgYdVqCL6baJ4Ku"></span></p><h3 id="leap-year-algorithm" tabindex="-1">Leap-Year Algorithm <a class="header-anchor" href="#leap-year-algorithm" aria-label="Permalink to &quot;Leap-Year Algorithm&quot;">​</a></h3><p><span id="source-block-SmEDFRTyh8P5P9V7gXt3Kh"></span></p><h3 id="euler-algorithm" tabindex="-1">Euler Algorithm <a class="header-anchor" href="#euler-algorithm" aria-label="Permalink to &quot;Euler Algorithm&quot;">​</a></h3><p><span id="source-block-xQRRd0h5FlKNP3iUeDlYjq"></span></p><h2 id="classical-logistics-theory" tabindex="-1">Classical Logistics Theory <a class="header-anchor" href="#classical-logistics-theory" aria-label="Permalink to &quot;Classical Logistics Theory&quot;">​</a></h2></div>',1)])])}const f=t(o,[["render",s]]);export{d as __pageData,f as default};
